\u0025\u0076\u0049\u007a\u0033\u0063\u0067\u0059\u0025\u0063\u006b\u002f\u0077\u0066\u0051\u0049\u0030\u0071\u004e\u002a\u006d\u004e\u0063\u0067\u003f\u0025\u0074\u0054\u0025\u004e\u0039\u003a\u004b\u006f\u004a\u0041\u002e\u003f\u007a\u0067\u0047\u002e\u005d\u0069\u004a\u0054\u0046\u002e\u002e\u0077\u007e\u0055\u002b\u0073\u0070\u0045\u0041\u0067\u0042\u0031\u007b\u007a\u0053\u0071\u002f\u004a\u005f\u0024\u0029\u0045\u0061\u006d\u0067\u0041\u0067\u006f\u006a\u0060\u0064\u0071\u002f\u0075\u007e\u007a\u002e\u0022\u0037\u0047\u003b\u002b\u004f\u003b\u0055\u005d\u0055\u007c\u006b\u0076\u0036\u003b\u0048\u0054\u002f\u0029\u0053\u0057\u0026\u0070\u0068\u004d\u0038\u004f\u0068\u0052\u0057\u0042\u0042\u0032\u0063\u0057\u0055\u0060\u0052\u0043\u006b\u0039\u004b\u0038\u006e\u0078\u0025\u0043\u0073\u0052\u0072\u007c\u004e\u0066\u002f\u003f\u0067\u0062\u004a\u006d\u0054\u006a\u002e\u006a\u003c\u0048\u004e\u003f\u007c\u0047\u0032\u0043\u006b\u0037\u0057\u0064\u0050\u0055\u0034\u0062\u006b\u0068\u0072\u004c\u0079\u004f\u003a\u005e\u0070\u0075\u0074\u003c\u0040\u005d\u005d\u005b\u005a\u0025\u0035\u006b\u0051\u0030\u002a\u002e\u003d\u004b\u004b\u004e\u0076\u0042\u006f\u0065\u0035\u0037\u0060\u0065\u0024\u003c\u002f\u006c\u006c\u0047\u0033\u0056\u0076\u006c\u0066\u0076\u006b\u0070\u0023\u0058\u004b\u005d\u0065\u0077\u0024\u0071\u0024\u006b\u003e\u0033\u0071\u004f\u0030\u006a\u005f\u005b\u0074\u004c\u005f\u0041\u0074\u002c\u004e\u0044\u0044\u0070\u006b\u002f\u0064\u0070\u005a\u005a\u0044\u0058\u0028\u0045\u0047\u0060\u0038\u0038\u0071\u0050\u0022\u0061\u0062\u0057\u004f\u002f\u002e\u0025\u005e\u0031\u0045\u0041\u0054\u003f\u004d\u0028\u0070\u0030\u0048\u003c\u002e\u0055\u0041\u0028\u0064\u0048\u002f\u0049\u0026\u0035\u0049\u0068\u0074\u0030\u006c\u0052\u0032\u003d\u0054\u003a\u003a\u006e\u004f\u0028\u0062\u007e\u0025\u0040\u0061\u0064\u002a\u0052\u0021\u0040\u0038\u0054\u007d\u0021\u0046\u0036\u007d\u005f\u0076\u004d\u002e\u002c\u007d\u0068\u0038\u0033\u0041\u0049\u0047\u0033\u007c\u0076\u0047\u004f\u003c\u0064\u004e\u006a\u0037\u0079\u0050\u006b\u006b\u006c\u0074\u0044\u0065\u0045\u003e\u0049\u0051\u0075\u0050\u0050\u006a\u0041\u004e\u006d\u0058\u0073\u0048\u0049\u0040\u0066\u0032\u0040\u0030\u006b\u0051\u003b\u0038\u0055\u007d\u003c\u004a\u003f\u007d\u0051\u0066\u0038\u0079\u003e\u007d\u0064\u0037\u0056\u002f\u0064\u0023\u0074\u0044\u0065\u0045\u007b\u0041\u0030\u0047\u003b\u0062\u0058\u0069\u0066\u0058\u0075\u007d\u0046\u0045\u0059\u0041\u005d\u0053\u006d\u0025\u0065\u0041\u0029\u0063\u003b\u006a\u0067\u003f\u0053\u0051\u004c\u0034\u0073\u0072\u0039\u003b\u002c\u0055\u0047\u0062\u003e\u006d\u0079\u002b\u0048\u0070\u0045\u0037\u004e\u004e\u0033\u002f\u007b\u0040\u004a\u007e\u0077\u007c\u0041\u004d\u0065\u002a\u0043\u002c\u005e\u007a\u0055\u006b\u0035\u0053\u006e\u007b\u0040\u0067\u005b\u0022\u004e\u0075\u0067\u0039\u005a\u0057\u004a\u005f\u0033\u0077\u002b\u0070\u003b\u005d\u006a\u005e\u003f\u0070\u004f\u0058\u0072\u0044\u0036\u004a\u006b\u0030\u005b\u003b\u0030\u0062\u0057\u0026\u002e\u0076\u0059\u0065\u0035\u0031\u0077\u0071\u0078\u0076\u0059\u0079\u004c\u0032\u0040\u006d\u0028\u0049\u0033\u0072\u0054\u006a\u0025\u007b\u0062\u0028\u0061\u0057\u0067\u0057\u006a\u0024\u006c\u0030\u0070\u0039\u0039\u0046\u006d\u0031\u004b\u0072\u0050\u0079\u005f\u0030\u0029\u0076\u0068\u0038\u0062\u006e\u0043\u006b\u0066\u0032\u0040\u004a\u0033\u0022\u007d\u0076\u006d\u0032\u002e\u004a\u0033\u0070\u0075\u0053\u007d\u005e\u0066\u0042\u005a\u0033\u007b\u006c\u0045\u0046\u0039\u003a\u0052\u0058\u0063\u0052\u0039\u0051\u007d\u0071\u0051\u0035\u0030\u0033\u0076\u0055\u002b\u003f\u006e\u0035\u0071\u005f\u0052\u004a\u002a\u002c\u0072\u0037\u0070\u0054\u003b\u007d\u003a\u0077\u0035\u0061\u004f\u0042\u0071\u0076\u0028\u004d\u0067\u005d\u005b\u0066\u002a\u0078\u0040\u0061\u0049\u0037\u0039\u0058\u0056\u0070\u0031\u0025\u006d\u007b\u003f\u004f\u0036\u0077\u0078\u0069\u007b\u0054\u005e\u004a\u0038\u0033\u005d\u006c\u006f\u0058\u0034\u0064\u004c\u0044\u0028\u0077\u003c\u0026\u0051\u0045\u0025\u002e\u0022\u0039\u006a\u0023\u0069\u003c\u0077\u0067\u006c\u0022\u0041\u004f\u0036\u0045\u0025\u0076\u0031\u0068\u006c\u0038\u0026\u002c\u0062\u003a\u0054\u007a\u0050\u006a\u0068\u0036\u007a\u0052\u003c\u0037\u0055\u005f\u0078\u0070\u007e\u0058\u0046\u0066\u0033\u0033\u003f\u0064\u0041\u0061\u0070\u0063\u0077\u0070\u0035\u006d\u0065\u007a\u006a\u0038\u006a\u0068\u0030\u0069\u003d\u005e\u004b\u0050\u003c\u0076\u007c\u003b\u0054\u005a\u0023\u0025\u0053\u003b\u003f\u0039\u0049\u004e\u0033\u003f\u0055\u0031\u0039\u003a\u0065\u004a\u0046\u0025\u0075\u0075\u0058\u004d\u0026\u005e\u0063\u004d\u0065\u005b\u0021\u006e\u0043\u002a\u0033\u0049\u0076\u0043\u003c\u006f\u004c\u004a\u0045\u0040\u0062\u0028\u0024\u004d\u0034\u004a\u006a\u005e\u0035\u0031\u0074\u002f\u0047\u0034\u006d\u004e\u003b\u0028\u0033\u005b\u0042\u0067\u0050\u004d\u002c\u003c\u0045\u0051\u0054\u0078\u002f\u0068\u0022\u0032\u005b\u0045\u0039\u005d\u007b\u0066\u0068\u0040\u0063\u0045\u0047\u005d\u003f\u0029\u0023\u003c\u0044\u0070\u0052\u0025\u0029\u0050\u0071\u0032\u0024\u0030\u0040\u005b\u007b\u0075\u0068\u0028\u005f\u007d\u005e\u005e\u0025\u0022\u005b\u0026\u002f\u0025\u0063\u006a\u0038\u0062\u0047\u0062\u0046\u003a\u004f\u002b\u0079\u002b\u0040\u0061\u0036\u005f\u007e\u0053\u0059\u0066\u002e\u0060\u0054\u0043\u002e\u0069\u0062\u0021\u0045\u0056\u0071\u0037\u0043\u0059\u0066\u0072\u007b\u0056\u007c\u0068\u0026\u003f\u0039\u0044\u0051\u0028\u0024\u007e\u003e\u0041\u0059\u0024\u005b\u0075\u0050\u006e\u002b\u0076\u0064\u0057\u0064\u002e\u004a\u0030\u0049\u0075\u002c\u005f\u0068\u0033\u0036\u003b\u0066\u0035\u0034\u004e\u0067\u0032\u0058\u0068\u0035\u0071\u003c\u0028\u0076\u0038\u0058\u0072\u005e\u0066\u0042\u0028\u006c\u0068\u0049\u0055\u0073\u0029\u0040\u0058\u0031\u0045\u005f\u003c\u0051\u0066\u007d\u006d\u0034\u0066\u0041\u006d\u0051\u0061\u0023\u0056\u0043\u0066\u002e\u0049\u004f\u0047\u0058\u0036\u0078\u0025\u005f\u003b\u0042\u0064\u0033\u0040\u0021\u0059\u0049\u004b\u0070\u0053\u0045\u005b\u004d\u003e\u0030\u0060\u006a\u0077\u0076\u0043\u0044\u004b\u0040\u0048\u0070\u0063\u0054\u0053\u0051\u006f\u0073\u0031\u0044\u006d\u0070\u0029\u0068\u0063\u006b\u0078\u003e\u0026\u0048\u004d\u006a\u006b\u0048\u0076\u0063\u0059\u0042\u006e\u0026\u0072\u007a\u0036\u006d\u006f\u005e\u006b\u0044\u0077\u0042\u004a\u0053\u0067\u0078\u0035\u0048\u002e\u0071\u0070\u0046\u0034\u0045\u0062\u0048\u0047\u0034\u0028\u0026\u0028\u003e\u0052\u0040\u0054\u002c\u0060\u0051\u0057\u0021\u004d\u0079\u003b\u0050\u0028\u0038\u003a\u003d\u007a\u0041\u0079\u0072\u002c\u0047\u007a\u003f\u0033\u004a\u0068\u0072\u0073\u005e\u003b\u0048\u0066\u0070\u005e\u0077\u0057\u0060\u0071\u004c\u002b\u0021\u0068\u0072\u0031\u0030\u0070\u0058\u0044\u0071\u0040\u0051\u002e\u0021\u0025\u002e\u003e\u0026\u0049\u0036\u0075\u0030\u0079\u005b\u0028\u004d\u006b\u0031\u0058\u002a\u0031\u0060\u002f\u0070\u0075\u0057\u0045\u0074\u0041\u007e\u0049\u005f\u0021\u0031\u0061\u0062\u006f\u004b\u0077\u0030\u0070\u0050\u005a\u005e\u002c\u0037\u0065\u004d\u0030\u0040\u002e\u0021\u0062\u0078\u005f\u006b\u0041\u0057\u0042\u005e\u002c\u0078\u005b\u005e\u0028\u003b\u007c\u0063\u0060\u0078\u0072\u0026\u0071\u006b\u0079\u0062\u005f\u0028\u002a\u0049\u006b\u0022\u005a\u0051\u0050\u0063\u003e\u002b\u0062\u0036\u0070\u005f\u0032\u007c\u0055\u003d\u002f\u0051\u0029\u0054\u0069\u007b\u002a\u002b\u0022\u003d\u0069\u0071\u007e\u003b\u0073\u004a\u0031\u0037\u0072\u0021\u0067\u005d\u0062\u004a\u0032\u005b\u006e\u0053\u0045\u004e\u007b\u0036\u0045\u0038\u0062\u0028\u002b\u0032\u007c\u0046\u004d\u0021\u0063\u007b\u0038\u007b\u0028\u0059\u0049\u0070\u004e\u0066\u002f\u007b\u007d\u0060\u0046\u005a\u0068\u007c\u0042\u0056\u0038\u0038\u003a\u0049\u0032\u0038\u0049\u0047\u0069\u002a\u0028\u002a\u0024\u0038\u0029\u0054\u0069\u007b\u002a\u002b\u007e\u0045\u0070\u0061\u004c\u0071\u004a\u0034\u002a\u0049\u0064\u0043\u002a\u0045\u0049\u005b\u007a\u005f\u002c\u0064\u0060\u0061\u0049\u0036\u005b\u0026\u007a\u0034\u0051\u0022\u003c\u0039\u006e\u0078\u0066\u0053\u0045\u0073\u005b\u0061\u0068\u0062\u0021\u0021\u005d\u0068\u0026\u0063\u0043\u0047\u004e\u005b\u0068\u0023\u0068\u004e\u0047\u002e\u0049\u007e\u0079\u003f\u0063\u0066\u0073\u0035\u0079\u0049\u007c\u004c\u004a\u0056\u0024\u003c\u0045\u0021\u0040\u0032\u007c\u0030\u0061\u0075\u0049\u0067\u006e\u0029\u004b\u0026\u0079\u0049\u0037\u0072\u0049\u0071\u0041\u0048\u005f\u0036\u0031\u0021\u0029\u005a\u003b\u0059\u007d\u0023\u0026\u0077\u007b\u006d\u0071\u0076\u0075\u0021\u006e\u006f\u0054\u005f\u0055\u004e\u0037\u0075\u003b\u0025\u006f\u0069\u0021\u0054\u0067\u006d\u0044\u0049\u0078\u0041\u0060\u005d\u0077\u005f\u007a\u007e\u0039\u0063\u006e\u0047\u0073\u0022\u0051\u0031\u0049\u006b\u0069\u002f\u0062\u0047\u0060\u0077\u007c\u0063\u0054\u0032\u0064\u0043\u005a\u005a\u0053\u0032\u006f\u0069\u004a\u0032\u004d\u003a\u0035\u0045\u0055\u0055\u0069\u0062\u0035\u007c\u0047\u006b\u003e\u003f\u0045\u007e\u0054\u0062\u002f\u005e\u0045\u004c\u007d\u0062\u007b\u003b\u007a\u007a\u0035\u004f\u0037\u0056\u0047\u0040\u0037\u004a\u006d\u0041\u0067\u004f\u0066\u0072\u0074\u004e\u0022\u005a\u0023\u006c\u006d\u0028\u0060\u0032\u0058\u0057\u0053\u0045\u0056\u0050\u004a\u0066\u006c\u0067\u003b\u007a\u0040\u0030\u0042\u0062\u0034\u0072\u003d\u0058\u003a\u0061\u0047\u0035\u0068\u007c\u0075\u0025\u0051\u0059\u0076\u0037\u0043\u0054\u0059\u0049\u007e\u0061\u005f\u0043\u004c\u004f\u0052\u003a\u0039\u0026\u0059\u0037\u0038\u0038\u0060\u0032\u006b\u006e\u0035\u0033\u004c\u004f\u005e\u0068\u003c\u003f\u0041\u0076\u003c\u005a\u0024\u0026\u0079\u0049\u0026\u0074\u0071\u0043\u0035\u007d\u0047\u0079\u006f\u0033\u0063\u003d\u0029\u006d\u0034\u003a\u0049\u0032\u0070\u0056\u0045\u0039\u0056\u0069\u0066\u007d\u005f\u003f\u0068\u005f\u002a\u0035\u0026\u0060\u0021\u0055\u007c\u007b\u006c\u007d\u0049\u004e\u003c\u0034\u005e\u0030\u0068\u006c\u0067\u007b\u007d\u0021\u006f\u0066\u0075\u004a\u005e\u006c\u006d\u0061\u0038\u0033\u0022\u0068\u0032\u0038\u0037\u0028\u0023\u0035\u0034\u0074\u0061\u0031\u0074\u004a\u0052\u0078\u004a\u0056\u0022\u0029\u0053\u0076\u0034\u004c\u005a\u0062\u0046\u0032\u0067\u003f\u0060\u0031\u004e\u007c\u004d\u003f\u0062\u0059\u0029\u0055\u0047\u0046\u0072\u005b\u0054\u007b\u0024\u0047\u0039\u0065\u0048\u002c\u003a\u0028\u0040\u0062\u0077\u007a\u0051\u004a\u0026\u0021\u006e\u0073\u0072\u0043\u0055\u0047\u005b\u003e\u003e\u0054\u0076\u0028\u0056\u0043\u0066\u004f\u0062\u0066\u0036\u007e\u0053\u007a\u0038\u0044\u006e\u0070\u0045\u0056\u0031\u0025\u0065\u0047\u0055\u006f\u0055\u0062\u0029\u003f\u0023\u002e\u006c\u006c\u0052\u0056\u0044\u0029\u002f\u0064\u0022\u0043\u007d\u003f\u0037\u004d\u0051\u0037\u004a\u0054\u0048\u0050\u0065\u0023\u0039\u0048\u007d\u0033\u0049\u002f\u007c\u0029\u0028\u0047\u005f\u004f\u006e\u002f\u0038\u0063\u002c\u0025\u0042\u004a\u003e\u004d\u003e\u005e\u0072\u0021\u0058\u006a\u003b\u004e\u002c\u006e\u003c\u0042\u0039\u0051\u0061\u0078\u003e\u0042\u002b\u006e\u007d\u007c\u0030\u0054\u0038\u0035\u0038\u003c\u0038\u004c\u0030\u006d\u0070\u0044\u0050\u0076\u0061\u0077\u0049\u002a\u0064\u005e\u004c\u0059\u0057\u0030\u0040\u0032\u0039\u0051\u0062\u0059\u002a\u003e\u004d\u0038\u007a\u002a\u0064\u0059\u0057\u006b\u007c\u003f\u007c\u0030\u0055\u0022\u0030\u0078\u004e\u0074\u0047\u004d\u0056\u0054\u0066\u0066\u005f\u005f\u007c\u0030\u003e\u0025\u002f\u0073\u0045\u006c\u005f\u005e\u002a\u0064\u0047\u0021\u0058\u0063\u0042\u0042\u006b\u005d\u0023\u0045\u0051\u0039\u0078\u007b\u0036\u0021\u0054\u005e\u0066\u0064\u0034\u0039\u007d\u006b\u005a\u002e\u0050\u0059\u0046\u006f\u0037\u0067\u0031\u0040\u0045\u003d\u007b\u0075\u0053\u006b\u0047\u0056\u003b\u0070\u0048\u0040\u0064\u007d\u0047\u0032\u007c\u0059\u0046\u0042\u007b\u006b\u0076\u007c\u0065\u007b\u0031\u0033\u0077\u004e\u0054\u0023\u0036\u0063\u007b\u0056\u0028\u0035\u003b\u0040\u003f\u006c\u0054\u0077\u0074\u0061\u0030\u0021\u0030\u0038\u002f\u0032\u0023\u0045\u006c\u0036\u005a\u003e\u0030\u0065\u003f\u0076\u0032\u0059\u0059\u0035\u0051\u0049\u007e\u005d\u0050\u007e\u007e\u005e